import{_ as r,l as t,o as a,c as i,v as o,p as d,x as s,d as l,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"InnoDB 对 Postgres 堆","description":"","frontmatter":{"title":"InnoDB 对 Postgres 堆","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/innodb-vs-postgres-storage.md","filePath":"cs/innodb-vs-postgres-storage.md","lastUpdated":1789023840000}'),B={name:"cs/innodb-vs-postgres-storage.md"};function E(h,e,D,I,u,g){const n=t("Mermaid");return a(),i("div",null,[e[1]||(e[1]=o('<h1 id="innodb-对-postgres-堆" tabindex="-1">InnoDB 对 Postgres 堆 <a class="header-anchor" href="#innodb-对-postgres-堆" aria-label="Permalink to &quot;InnoDB 对 Postgres 堆&quot;">​</a></h1><div class="epigraph"><p>InnoDB 主键即聚簇：行跟在主键叶上。Postgres 堆是无序页，索引一律二次查找。两种页合同决定回表、覆盖与 vacuum 的形状。</p><footer>—— 据 Ramakrishnan and Gehrke 聚簇；InnoDB 与 PostgreSQL 存储文档；Gray</footer></div><p><a href="/cs/tde-compression">上一课</a>把加密放在 I/O 路径。本课打开引擎对照：同样关系代数，行放哪。缺口不是再定义 B+，而是两条工业路径——聚簇索引表 vs 堆+二级索引——对覆盖、范围扫描、MVCC 版本落点的影响。细节 undo/redo、vacuum 后课补。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>聚簇（索引组织）：按主键序存整行，主键范围扫描是顺序 I/O，二级索引存主键（再回聚簇）或存 RID。堆：插入常追加，物理序与主键无关，主键也是二级结构，RID 指堆槽。缺口是<strong>默认访问路径</strong>：<code>WHERE pk BETWEEN</code> 在 InnoDB 走叶链；在 Postgres 走主键索引再随机堆，除非额外 <code>CLUSTER</code>（一次性，不维持）。</p><p>更新主键在聚簇里等于搬行；堆上改主键只改索引项。宽行、溢出页两边都有，但叶页变宽使 InnoDB 扇出下降。</p><p><span class="marginnote">教材里 index-organized vs heap-organized。本课用两家引擎当实例，不把版本号当理论。覆盖索引课已有逻辑，这里是物理落点。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选主键时，InnoDB 要认真：单调键减少页分裂；UUID 随机插入打散叶、碎缓冲。Postgres 主键选择不决定堆序，要用 <code>BRIN</code>/分区/CLUSTER 表达序。二级索引：InnoDB 回表是回主键；Postgres 回表是回堆——随机 I/O 模型不同，校准分开。</p><p>MVCC：Postgres 版本在堆行头（多版本行）；InnoDB 旧版本常进 undo，聚簇叶上是当前行。下一课与 vacuum 课分别钉。</p>',10)),(a(),d(c,null,{default:s(()=>[p(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20INN%5B%22InnoDB%22%5D%20--%3E%20CL%5B%22%E4%B8%BB%E9%94%AE%E5%8F%B6%E4%B8%8A%E5%8D%B3%E8%A1%8C%22%5D%0A%20%20INN%20--%3E%20SEC%5B%22%E4%BA%8C%E7%BA%A7%E9%94%AE%E5%88%B0%E4%B8%BB%E9%94%AE%22%5D%0A%20%20PG%5B%22Postgres%22%5D%20--%3E%20HEAP%5B%22%E5%A0%86%E6%A7%BD%E5%AD%98%E8%A1%8C%E7%89%88%E6%9C%AC%22%5D%0A%20%20PG%20--%3E%20IDX%5B%22%E6%89%80%E6%9C%89%E7%B4%A2%E5%BC%95%E5%88%B0%20TID%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>缓冲池：聚簇把行与主键叶同一页，点查 pk 少一次 I/O；二级仍两次。堆点查主键两次（索引+堆）。延迟物化：堆上 TID 列表再堆取，即 bitmap heap scan 一类。</p><p>锁：聚簇间隙与记录锁贴在主键序上；堆上锁贴 TID 与索引。后课间隙锁。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 doublewrite。也不把 MyISAM 写进对照。索引组织表课会抽象 InnoDB 这一侧，Oracle IOT 点名。</p><p>后课默认：谈到行位置，先问聚簇还是堆。undo/redo 与 doublewrite：日志与页撕裂如何配这两套页。</p><p>没有谁绝对更快；范围主键 vs 随机主键把结论反转。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>InnoDB 聚簇主键存行；Postgres 堆无序，索引都回 TID。</li><li>回表次数与页分裂模式因此不同。</li><li>undo/redo 与 doublewrite 下一课。</li><li>出处：Ramakrishnan and Gehrke；InnoDB/Postgres 存储文档。</li></ul>',9))])}const P=r(B,[["render",E]]);export{m as __pageData,P as default};
